let universe='marvel',view='Explore',filter='All',zoom=1,pan={x:0,y:0},history=[],saved=[],level=3;try{saved=JSON.parse(localStorage.getItem('loreverse-saved')||'[]');if(!Array.isArray(saved))saved=[];level=Number(localStorage.getItem('loreverse-level')??3);if(![0,1,2,3].includes(level))level=3}catch{}let data=()=>universes[universe],visible=()=>data().nodes.filter(n=>n.level<=level),edges=()=>data().edges.filter(e=>e[3]<=level&&visible().some(n=>n.id===e[0])&&visible().some(n=>n.id===e[1])),entity=id=>data().nodes.find(n=>n.id===id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}function persist(){try{localStorage.setItem('loreverse-saved',JSON.stringify(saved));localStorage.setItem('loreverse-level',level)}catch{notify('Storage unavailable. Changes last for this session.')}}function art(n){const p=palettes[n.color];return `<div class="art" style="--glow:${p[0]};--light:${p[1]}"><span class="art-label">${n.type.toUpperCase()}</span><span class="sigil">${n.sigil}</span></div>`}function card(n){const count=edges().filter(e=>e[0]===n.id||e[1]===n.id).length;return `<button class="entity-card" data-entity="${n.id}">${art(n)}<div class="card-body"><h3>${n.name}</h3><p>${n.subtitle}</p><div class="card-bottom"><span>⌘ &nbsp; ${count} connections</span><span>Explore lore ↗</span></div></div></button>`}function openModal(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();wireModal()}function title(t,p,action=''){return `<div class="page-title"><div><h1>${t}</h1><p>${p}</p></div>${action}</div>`}function graphMarkup(large=false){let ns=visible();if(!large)ns=ns.slice(0,8);if(filter!=='All'&&large)ns=ns.filter(n=>n.type===filter);const width=700,height=large?510:290,cx=350,cy=height/2,r=large?190:104;const positions={};ns.forEach((n,i)=>{const a=i/ns.length*Math.PI*2-Math.PI/2;positions[n.id]={x:cx+Math.cos(a)*r*(large?1.35:1.6),y:cy+Math.sin(a)*r*.82}});const es=edges().filter(e=>positions[e[0]]&&positions[e[1]]);return `<div class="graph-wrap ${large?'large':''}"><svg viewBox="0 0 ${width} ${height}" aria-label="Interactive lore relationship graph"><g id="graphTransform">${es.map(e=>{let a=positions[e[0]],b=positions[e[1]];return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#655077" stroke-width="1" opacity=".65"/>${large?`<text x="${(a.x+b.x)/2}" y="${(a.y+b.y)/2}" fill="#9f87b0" font-size="8" text-anchor="middle" paint-order="stroke" stroke="#17131e" stroke-width="4">${e[2]}</text>`:''}`}).join('')}${ns.map(n=>{let p=positions[n.id];return `<g class="graph-node" data-entity="${n.id}" tabindex="0" role="button" aria-label="Explore ${n.name}" transform="translate(${p.x},${p.y})"><circle r="22" fill="#272030" stroke="${palettes[n.color][1]}" stroke-width="1"/><text text-anchor="middle" y="7" font-size="23" fill="${palettes[n.color][1]}">${n.sigil}</text><text text-anchor="middle" y="37" fill="#c9bed7" font-size="9" paint-order="stroke" stroke="#17131e" stroke-width="4">${n.name}</text></g>`}).join('')}</g></svg><div class="graph-controls"><button id="zoomOut" aria-label="Zoom out">−</button><button id="resetGraph" aria-label="Reset graph">⊙</button><button id="zoomIn" aria-label="Zoom in">+</button></div></div><div class="legend"><span><b>●</b> Characters</span><span><b>●</b> Factions & objects</span><span>Click a node to follow its story</span></div>`}
function render(){const d=data();$('#universeName').textContent=d.full;$('.marvel-mini').textContent=universe==='marvel'?'M':'G';$('#crumb').textContent=d.name;$('#saveCount').textContent=saved.length;$('#spoilerLabel').textContent=level===3?'All lore visible':d.levels[level];$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));let html='';if(view==='Explore'){const chars=visible().filter(n=>n.type==='Character').slice(0,4);html=title('A whole universe awaits.','Go beyond the story. Discover what connects it all.',`<button class="outline" id="connectOpen">⌘ &nbsp; Connect two entities</button>`)+`<section class="hero"><div class="hero-content"><div class="eyebrow"><span class="badge">${universe==='marvel'?'MARVEL':'GOT'}</span>${d.tag}</div><h2>${d.line.replace('\n','<br>')}</h2><p>${d.description}</p><button class="primary" data-view="Lore Graph">Explore the universe &nbsp; ↗</button><button class="outline" data-view="Timeline">◷ &nbsp; View timeline</button></div><span class="hero-stamp">${universe==='marvel'?'EARTH–616 · MCU':'WESTEROS · HBO SERIES'}</span></section><div class="stats"><span><i>♙</i><b>${visible().filter(n=>n.type==='Character').length}</b> Characters</span><span><i>⌘</i><b>${edges().length}</b> Connections</span><span><i>ϟ</i><b>${visible().filter(n=>n.type==='Event').length}</b> Key events</span><span><i>◈</i> One connected universe</span></div><div class="section-heading"><div><h2>Extraordinary characters. Intertwined stories.</h2><p>A few familiar faces. A thousand ways to explore.</p></div><button class="text-link" data-view="Characters">View all ↗</button></div><div class="cards">${chars.map(card).join('')}</div><div class="lower"><div><div class="section-heading"><h2>Follow the connections</h2><button class="text-link" data-view="Lore Graph">Open full graph ↗</button></div><section class="graph-panel"><div class="panel-top"><div><h3>Nothing exists in isolation.</h3><p>Every connection opens another story.</p></div><span style="color:#9370b4">⌘</span></div>${graphMarkup()}</section></div><div><div class="section-heading"><h2>A little deeper into the lore</h2><span style="color:#84728f">✧</span></div><section class="discovery"><span class="eyebrow">THE RABBIT HOLE</span><h3>${level>=3?d.discovery:'Every great story starts with a connection.'}</h3><p>${level>=3?d.discoveryText:'Explore the relationships available at your viewing progress. There is always another thread to follow.'}</p><div class="mini-path">${(level>=3?d.discoverIds:visible().slice(0,3).map(n=>n.id)).map(id=>`<b>${entity(id).sigil}</b>`).join('─')}</div><button id="discover">Follow this story &nbsp; ↗</button></section></div></div>`}
else if(view==='Lore Graph'){html=title('The lore, connected.','Click a node to explore. Drag to pan. Use + and − to zoom.',`<button class="outline" id="connectOpen">⌘ &nbsp; Connect two entities</button>`)+`<div class="view-tabs">${['All','Character','Faction','Object','Event'].map(t=>`<button data-filter="${t}" class="${filter===t?'active':''}">${t==='All'?'All entities':t+'s'}</button>`).join('')}</div><section class="graph-panel">${graphMarkup(true)}</section><div class="note">${visible().length} entities and ${edges().length} relationships available at your spoiler setting. Relationship labels read from the source entity to the target.</div>`}
else if(view==='Timeline'){let ns=visible().filter(n=>n.type==='Event'||n.type==='Character').sort((a,b)=>a.year-b.year);html=title('A story across time.',universe==='marvel'?'Selected MCU milestones, ordered by in-universe year.':'Selected milestones, grouped by the season that introduces them.')+`<div class="timeline">${ns.map(n=>`<button class="timeline-item" data-entity="${n.id}"><span class="eyebrow">${universe==='marvel'?n.year:'SEASON '+n.year} · ${n.type}</span><h3>${n.name}</h3><p>${n.subtitle}</p></button>`).join('')}</div>`}
else if(view==='Lore Paths'){html=title('Let curiosity lead.','A guided route through the people and moments that shape a universe.')+`<section class="discovery"><span class="eyebrow">GUIDED EXPLORATION · ${data().path.filter(id=>visible().some(n=>n.id===id)).length} STOPS</span><h3>${universe==='marvel'?'From armor to infinity':'From the Wall to the throne'}</h3><p>Open each stop to learn its story and follow its connections.</p>${d.path.filter(id=>visible().some(n=>n.id===id)).map((id,i)=>`<div class="path-step"><span>0${i+1}</span><button data-entity="${id}">${entity(id).name}<small>${entity(id).subtitle}</small></button></div>`).join('')}</section>`}
else{let ns=visible().filter(n=>view==='Characters'?n.type==='Character':view==='Events'?n.type==='Event':view==='Factions'?['Faction','Object'].includes(n.type):saved.includes(universe+':'+n.id));html=title(view==='Bookmarks'?'Your saved lore.':view==='Factions'?'The forces behind the story.':view==='Events'?'Moments that changed everything.':'Meet the extraordinary.',view==='Bookmarks'?'Your collection, saved on this device. Spoiler settings still apply.':'Choose an entity to discover its story and connections.')+(ns.length?`<div class="cards grid-all">${ns.map(card).join('')}</div>`:`<div class="empty"><h2>${view==='Bookmarks'?'Your next discovery belongs here.':'More of the story lies ahead.'}</h2><p>${view==='Bookmarks'?'Open a profile and select Save lore to start a collection.':'No entries are available at this spoiler setting. Change your viewing progress to reveal more.'}</p></div>`)}$('#main').innerHTML=html;wire();}
function showEntity(id){const n=entity(id);if(!n||n.level>level)return;history.push(id);const related=edges().filter(e=>e[0]===id||e[1]===id);openModal(`${art(n)}<span class="eyebrow">${n.type} · ${data().name}</span><h2>${n.name}</h2><p style="color:#c3a9e0">${n.subtitle}</p><div class="actions"><button class="primary" id="saveEntity">${saved.includes(universe+':'+id)?'✓ Saved lore':'＋ Save lore'}</button><button class="outline" id="entityGraph">Explore graph ↗</button></div><p>${n.description}</p><p class="source">Source: ${n.source}<br>Continuity: ${universe==='marvel'?'Marvel Cinematic Universe':'HBO television series'} · Curated summary</p><h3>Connected stories <span style="color:#8b759f">${related.length}</span></h3>${related.map(e=>{const other=entity(e[0]===id?e[1]:e[0]);return `<button class="result" data-entity="${other.id}"><b>${other.name}</b><span>${entity(e[0]).name} → ${e[2]} → ${entity(e[1]).name}</span></button>`}).join('')||'<p>No connections are available at this viewing progress.</p>'}<p class="source">Your rabbit hole: ${history.length} ${history.length===1?'story':'stories'} explored this session</p>`);$('#saveEntity').onclick=()=>{const key=universe+':'+id;if(saved.includes(key))saved=saved.filter(x=>x!==key);else saved.push(key);persist();$('#saveEntity').textContent=saved.includes(key)?'✓ Saved lore':'＋ Save lore';$('#saveCount').textContent=saved.length;if(view==='Bookmarks')render()};$('#entityGraph').onclick=()=>{$('#modal').close();view='Lore Graph';filter='All';render()};}
function wireModal(){$$('#modal [data-entity]').forEach(b=>b.onclick=()=>showEntity(b.dataset.entity))}function wire(){$$('#main [data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$$('#main [data-entity]').forEach(b=>{b.onclick=()=>showEntity(b.dataset.entity);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showEntity(b.dataset.entity)}}});$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});if($('#connectOpen'))$('#connectOpen').onclick=showConnect;if($('#discover'))$('#discover').onclick=()=>showEntity(level>=3?data().discoverIds[0]:visible()[0].id);if($('#zoomIn')){$('#zoomIn').onclick=()=>{zoom=Math.min(2.5,zoom+.2);transformGraph()};$('#zoomOut').onclick=()=>{zoom=Math.max(.6,zoom-.2);transformGraph()};$('#resetGraph').onclick=()=>{zoom=1;pan={x:0,y:0};transformGraph()};const svg=$('.graph-wrap svg');let drag=null;svg.onpointerdown=e=>{if(e.target.closest('.graph-node'))return;drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};svg.setPointerCapture(e.pointerId)};svg.onpointermove=e=>{if(!drag)return;const scale=700/svg.getBoundingClientRect().width;pan={x:drag.px+(e.clientX-drag.x)*scale,y:drag.py+(e.clientY-drag.y)*scale};transformGraph()};svg.onpointerup=()=>drag=null;svg.onpointercancel=()=>drag=null;transformGraph()}}
function transformGraph(){const el=$('#graphTransform');if(el)el.setAttribute('transform',`translate(${350*(1-zoom)+pan.x},${(view==='Lore Graph'?255:145)*(1-zoom)+pan.y}) scale(${zoom})`)}function go(v){view=v;filter='All';zoom=1;pan={x:0,y:0};render();window.scrollTo(0,0)}
function shortestPath(a,b){let queue=[[a]],seen=new Set([a]);while(queue.length){let path=queue.shift(),last=path.at(-1);if(last===b)return path;for(const e of edges()){let next=e[0]===last?e[1]:e[1]===last?e[0]:null;if(next&&!seen.has(next)){seen.add(next);queue.push([...path,next])}}}return null}
function showConnect(){const ns=visible();openModal(`<span class="eyebrow">SIX DEGREES OF LORE</span><h2>Everything is connected.</h2><p>Find the shortest relationship path between two entities in the current lore graph.</p><div class="form-row"><label style="flex:1">From<select id="from" aria-label="From">${ns.map(n=>`<option value="${n.id}">${n.name}</option>`).join('')}</select></label><label style="flex:1">To<select id="to" aria-label="To">${ns.map((n,i)=>`<option value="${n.id}" ${(universe==='got'?i===1:i===ns.length-1)?'selected':''}>${n.name}</option>`).join('')}</select></label></div><button class="primary" id="findPath">Find connection ↗</button><div id="pathOutput" aria-live="polite"></div><p class="source">Paths traverse curated relationships in either direction and respect your spoiler setting.</p>`);$('#findPath').onclick=()=>{const p=shortestPath($('#from').value,$('#to').value);$('#pathOutput').innerHTML=p?`<div class="path-result">${p.map(id=>`<button data-entity="${id}">${entity(id).name}</button>`).join('<span>→</span>')}</div><p class="source">${p.length-1} connection${p.length===2?'':'s'} · ${p.length===1?'You selected the same entity.':'Click any stop to explore.'}</p>`:'<div class="note">No path exists in the available dataset at this spoiler setting. Try another pair or adjust viewing progress.</div>';wireModal()}}
function showSearch(){openModal(`<span class="eyebrow">FOLLOW YOUR CURIOSITY</span><h2>What will you discover?</h2><input id="search" aria-label="Search lore" placeholder="Try Wanda, Infinity Stones, or the Wall…" autocomplete="off"><div class="note">Search curated names, descriptions, and sources. This demo does not use live AI or semantic search.</div><div id="results" class="results"></div>`);const run=()=>{const q=$('#search').value.trim().toLowerCase(),terms=q.split(/\s+/).filter(t=>!['who','what','is','the','a','and','how','does','to','of','in','are','me','about','explain'].includes(t));let ns=visible().map(n=>({n,score:terms.reduce((s,t)=>s+((n.name+' '+n.subtitle+' '+n.description+' '+n.source).toLowerCase().includes(t)?1:0),0)})).filter(x=>!q||x.score>0).sort((a,b)=>b.score-a.score).slice(0,7).map(x=>x.n);$('#results').innerHTML=ns.length?ns.map(n=>`<button class="result" data-entity="${n.id}"><b>${n.name}</b><span>${n.type} ↗</span></button>`).join(''):'<p>No matching lore at your current spoiler setting. Try a name or another keyword.</p>';wireModal()};$('#search').oninput=run;run();setTimeout(()=>$('#search').focus(),50)}
$('#searchOpen').onclick=showSearch;$('.close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}};document.onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();showSearch()}};$$('nav [data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();go('Explore')};$('#random').onclick=()=>{const ns=visible();showEntity(ns[Math.floor(Math.random()*ns.length)].id)};$('#universeSwitcher').onclick=()=>{openModal(`<span class="eyebrow">CHOOSE YOUR NEXT WORLD</span><h2>Enter the lore.</h2><p>Different worlds. Endless connections.</p>${Object.entries(universes).map(([key,d])=>`<button class="universe-option" data-universe="${key}"><strong>${d.full} ↗</strong><span>${d.tag} · ${d.nodes.length} curated entities</span></button>`).join('')}<p class="source">More worlds can be added to the same graph engine.</p>`);$$('[data-universe]').forEach(b=>b.onclick=()=>{universe=b.dataset.universe;history=[];$('#modal').close();go('Explore')})};$('#spoilerOpen').onclick=()=>{openModal(`<span class="eyebrow">EXPLORE AT YOUR OWN PACE</span><h2>Your story. Your progress.</h2><p>Only show entities and relationships introduced by your selected milestone. The sample uses broad milestones, not episode-level protection.</p><label for="progress" style="display:block;margin:22px 0 8px">I have watched up to</label><select id="progress">${data().levels.map((l,i)=>`<option value="${i}" ${i===level?'selected':''}>${l}</option>`).join('')}</select><div class="note">This setting applies to profiles, search, graphs, discovery, timelines, and connection paths. Saved lore beyond your progress is hidden.</div><button class="primary" id="applyProgress">Save viewing progress</button>`);$('#applyProgress').onclick=()=>{level=Number($('#progress').value);persist();$('#modal').close();render();notify('Viewing progress updated')}};render();
